function parseCompetencia(raw){
  const now=new Date(new Date().toLocaleString('en-US',{timeZone:'America/Sao_Paulo'}));
  if(raw==null||String(raw).trim()==='')return null;
  let s=String(raw).trim().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
  const nomes={jan:1,janeiro:1,fev:2,fevereiro:2,mar:3,marco:3,abr:4,abril:4,mai:5,maio:5,jun:6,junho:6,jul:7,julho:7,ago:8,agosto:8,set:9,setembro:9,out:10,outubro:10,nov:11,novembro:11,dez:12,dezembro:12};
  let m=s.match(/^(\d{1,2})\/(\d{4})$/);
  if(m)return m[2]+'-'+m[1].padStart(2,'0')+'-01';
  m=s.match(/^(\d{4})-(\d{1,2})(?:-\d{1,2})?$/);
  if(m)return m[1]+'-'+m[2].padStart(2,'0')+'-01';
  m=s.match(/^([a-z]+)(?:[\/\s-]+(\d{4}))?$/);
  if(m&&nomes[m[1]])return (m[2]||now.getFullYear())+'-'+String(nomes[m[1]]).padStart(2,'0')+'-01';
  return null;
}
