// Parser OFX/CSV para PB-4 (conta-corrente). Puro: roda local e dentro do n8n Code node.
// Exporta: detectFormat, parseOFX, parseCSV, normalize.
const crypto = require('crypto');

function detectFormat(text) {
  return /<OFX>|<STMTTRN>|OFXHEADER/i.test(text) ? 'ofx' : 'csv';
}

// le valor de uma tag SGML/OFX (valor = texto ate o proximo '<' ou quebra de linha)
function tag(block, name) {
  const m = block.match(new RegExp('<' + name + '>([^<\\r\\n]*)', 'i'));
  return m ? m[1].trim() : '';
}

function parseOFX(text) {
  const out = [];
  let blocks = text.match(/<STMTTRN>[\s\S]*?<\/STMTTRN>/gi);
  if (!blocks || blocks.length === 0) {
    // OFX SGML sem fechamento de tag: divide por <STMTTRN>
    blocks = text.split(/<STMTTRN>/i).slice(1).map(s => '<STMTTRN>' + s);
  }
  for (const b of blocks) {
    const trnamt = tag(b, 'TRNAMT');
    const dt = tag(b, 'DTPOSTED');
    const valor = parseFloat(String(trnamt).replace(',', '.'));
    if (isNaN(valor)) continue;
    const data = dt && dt.length >= 8 ? (dt.slice(0, 4) + '-' + dt.slice(4, 6) + '-' + dt.slice(6, 8)) : null;
    out.push({
      tipo: valor < 0 ? 'debito' : 'credito',
      valor: Math.abs(valor),
      data,
      descricao: (tag(b, 'MEMO') || tag(b, 'NAME') || '(sem descrição)').trim(),
      fitid: tag(b, 'FITID'),
      trntype: tag(b, 'TRNTYPE')
    });
  }
  return out;
}

function parseCSV(text) {
  const lines = text.split(/\r?\n/).filter(l => l.trim());
  if (!lines.length) return [];
  const sep = (lines[0].split(';').length > lines[0].split(',').length) ? ';' : ',';
  const header = lines[0].split(sep).map(h => h.trim().toLowerCase());
  const find = (...names) => { for (const n of names) { const i = header.findIndex(h => h.includes(n)); if (i >= 0) return i; } return -1; };
  const iData = find('data'), iValor = find('valor', 'amount'),
        iDesc = find('descri', 'histó', 'hist', 'title', 'estabelecimento'),
        iId = find('identificador', 'id ', 'idtransacao');
  const out = [];
  for (let i = 1; i < lines.length; i++) {
    const c = lines[i].split(sep).map(x => x.trim());
    if (c.length < 2) continue;
    let vRaw = (iValor >= 0 ? c[iValor] : '').replace(/r\$/i, '').replace(/\s/g, '');
    if (vRaw.includes(',')) vRaw = vRaw.replace(/\.(?=\d{3}(\D|$))/g, '').replace(',', '.');
    const valor = parseFloat(vRaw);
    if (isNaN(valor)) continue;
    const d = iData >= 0 ? c[iData] : '';
    let data = null;
    const m1 = d.match(/^(\d{2})\/(\d{2})\/(\d{4})/), m2 = d.match(/^(\d{4})-(\d{2})-(\d{2})/);
    if (m1) data = m1[3] + '-' + m1[2] + '-' + m1[1]; else if (m2) data = m2[1] + '-' + m2[2] + '-' + m2[3];
    out.push({
      tipo: valor < 0 ? 'debito' : 'credito',
      valor: Math.abs(valor),
      data,
      descricao: (iDesc >= 0 ? c[iDesc] : '') || '(sem descrição)',
      fitid: iId >= 0 ? c[iId] : '',
      trntype: ''
    });
  }
  return out;
}

function sha1(s) { return crypto.createHash('sha1').update(String(s)).digest('hex').slice(0, 16); }

// SO despesas (debito) viram gasto. Credito conta so no resumo.
// v1.1: flag 'fatura' (pagamento de fatura/cartao) e 'repasse' (mesmo valor entrou e saiu no dia) -> NAO promovem automatico.
function normalize(transacoes, banco, formato) {
  const credKeys = new Set();
  for (const t of transacoes) if (t.tipo === 'credito') credKeys.add(t.data + '|' + t.valor.toFixed(2));
  const itens = [];
  let creditos = 0;
  for (const t of transacoes) {
    if (t.tipo !== 'debito') { creditos++; continue; }
    let flag = 'ok', motivo = '';
    if (/fatura|cart[aã]o/i.test(t.descricao)) { flag = 'fatura'; motivo = 'pagamento de fatura/cartão (conflita com faturas)'; }
    else if (credKeys.has(t.data + '|' + t.valor.toFixed(2))) { flag = 'repasse'; motivo = 'mesmo valor entrou e saiu no mesmo dia'; }
    const base = (t.fitid && String(t.fitid).trim()) ? String(t.fitid).trim() : ('h:' + sha1([t.data, t.valor, t.descricao].join('|')));
    itens.push({
      origem: formato, banco, ext_id: banco + ':' + base,
      data_transacao: t.data, descricao: String(t.descricao).slice(0, 200),
      valor: Number(t.valor.toFixed(2)), flag, motivo
    });
  }
  return {
    despesas: itens.filter(i => i.flag === 'ok'),   // promovem
    revisar: itens.filter(i => i.flag !== 'ok'),    // ignorado sugerido / revisar
    creditos, total: transacoes.length
  };
}


